#!/usr/bin/env python3
# test_gif.py - tests for packages/video-export-qa/scripts/qa_gif.py (stdlib unittest, real ffmpeg).
#
# Purpose: prove qa_gif.py measures what it claims, and that each check can actually fail.
# Inputs:  none. GIF fixtures are generated by ffmpeg (or assembled byte by byte in this file)
#          under _work/video-export-qa/gif-compare/gif/. No user media is used.
# Outputs: unittest results; fixtures and measured_gif_delays.json in the _work folder.
# Run:     python -B -m unittest discover -s tests/video-export-qa -p "test_gif.py"
#
# Every check has a happy path and a negative control. The delay-rounding negative control
# binary-patches the Graphic Control Extension delay fields of an ffmpeg-made GIF (no encoder
# is written here). An independent oracle (ffprobe's GIF demuxer) cross-checks the parser.

import ast
import hashlib
import io
import json
import os
import re
import shutil
import struct
import subprocess
import sys
import time
import unittest

sys.dont_write_bytecode = True  # keep __pycache__ out of the package and the tests

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", ".."))
SCRIPTS = os.path.join(ROOT, "packages", "video-export-qa", "scripts")
GIF_SCRIPT = os.path.join(SCRIPTS, "qa_gif.py")
WORK = os.path.join(ROOT, "_work", "video-export-qa", "gif-compare", "gif")
sys.path.insert(0, SCRIPTS)

import common  # noqa: E402
import qa_gif  # noqa: E402

FFMPEG = shutil.which("ffmpeg")
FFPROBE = shutil.which("ffprobe")
F = {}  # fixture name -> path, filled by setUpModule


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def run_cmd(cmd):
    proc = subprocess.run(cmd, capture_output=True)
    if proc.returncode != 0:
        raise AssertionError("command failed: %s\n%s" % (cmd, proc.stderr.decode("utf-8", "replace")))
    return proc.stdout.decode("utf-8", "replace")


def ffmpeg_gif(name, fps=24, frames=24, extra=None, graph=None):
    """Make an ffmpeg GIF from a generated test pattern (64x48)."""
    path = os.path.join(WORK, name)
    cmd = [FFMPEG, "-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi",
           "-i", "testsrc2=size=64x48:rate=%s" % fps]
    if graph:
        cmd += ["-filter_complex", graph]
    # The default repeats the preceding delay; at 30 fps that can add 1 cs
    # depending on the encoder version. Specify the final frame's 3 cs delay.
    if fps == 30:
        cmd += ["-final_delay", "3"]
    cmd += ["-frames:v", str(frames)] + (extra or []) + [path]
    run_cmd(cmd)
    return path


def read(path):
    with open(path, "rb") as fh:
        return fh.read()


def write(name, data):
    path = os.path.join(WORK, name)
    with open(path, "wb") as fh:
        fh.write(data)
    return path


def oracle_delays(path):
    """Raw frame delays in centiseconds according to ffprobe's GIF demuxer (independent of qa_gif)."""
    out = run_cmd([FFPROBE, "-hide_banner", "-v", "error", "-min_delay", "0", "-select_streams", "v:0",
                   "-show_entries", "packet=duration", "-of", "csv=p=0", path])
    return [int(x) for x in out.split()]


def decoded_frame_count(path):
    out = run_cmd([FFPROBE, "-hide_banner", "-v", "error", "-count_frames", "-select_streams", "v:0",
                   "-show_entries", "stream=nb_read_frames", "-of", "csv=p=0", path])
    return int(out.strip())


GCE_PREFIX = b"\x21\xf9\x04"


def gce_offsets(data, expected):
    """Offsets of the Graphic Control Extensions of an ffmpeg-made GIF (byte pattern, then sanity checked)."""
    found = [m.start() for m in re.finditer(re.escape(GCE_PREFIX), data)]
    found = [i for i in found if i + 8 < len(data) and data[i + 7] == 0 and data[i + 8] == 0x2C]
    if len(found) != expected:
        raise AssertionError("expected %d graphic control extensions, found %d" % (expected, len(found)))
    return found


def patch_delays(data, delays):
    """Return a copy of an ffmpeg-made GIF with every frame delay replaced (int = same for all)."""
    offsets = gce_offsets(data, len(delays) if isinstance(delays, list) else qa_gif_frames(data))
    out = bytearray(data)
    for k, off in enumerate(offsets):
        value = delays[k] if isinstance(delays, list) else delays
        out[off + 4:off + 6] = struct.pack("<H", value)
    return bytes(out)


def qa_gif_frames(data):
    return len(qa_gif._parse_stream(io.BytesIO(data))["frames"])


def patch_interlace(data):
    """Set the interlace flag on every image descriptor of an ffmpeg-made GIF."""
    out = bytearray(data)
    for off in gce_offsets(data, qa_gif_frames(data)):
        out[off + 17] |= 0x40  # packed byte of the image descriptor that follows the GCE
    return bytes(out)


def patch_loop(data, count):
    out = bytearray(data)
    at = data.index(b"NETSCAPE2.0")
    assert data[at + 11] == 3 and data[at + 12] == 1, "unexpected NETSCAPE layout"
    out[at + 13:at + 15] = struct.pack("<H", count)
    return bytes(out)


# Hand-assembled GIFs (a 1x1 screen with a fixed, valid LZW stream; no encoder involved).

def u16(n):
    return struct.pack("<H", n)


def sub_blocks(payload):
    out = b""
    for i in range(0, len(payload), 255):
        chunk = payload[i:i + 255]
        out += bytes([len(chunk)]) + chunk
    return out + b"\x00"


def b_gce(delay, disposal=1, transparent=False):
    return b"\x21\xf9\x04" + bytes([(disposal << 2) | (1 if transparent else 0)]) + u16(delay) + b"\x00\x00"


def b_comment(text):
    return b"\x21\xfe" + sub_blocks(text)


def b_application(ident11, payload):
    return b"\x21\xff\x0b" + ident11 + sub_blocks(payload)


def b_netscape(loop):
    return b_application(b"NETSCAPE2.0", b"\x01" + u16(loop))


def b_plain_text(text):
    fixed = u16(0) + u16(0) + u16(1) + u16(1) + bytes([1, 1, 1, 0])
    return b"\x21\x01\x0c" + fixed + sub_blocks(text)


def b_frame(delay=4, with_gce=True, local=False, interlaced=False):
    packed = (0x80 | 0x01 if local else 0) | (0x40 if interlaced else 0)
    head = b_gce(delay) if with_gce else b""
    desc = b"\x2c" + u16(0) + u16(0) + u16(1) + u16(1) + bytes([packed])
    table = bytes(range(12)) if local else b""  # 4 colours
    return head + desc + table + b"\x02" + b"\x02\x44\x01\x00"  # LZW: clear, pixel 0, end


def build_gif(blocks, version=b"GIF89a", trailer=True):
    header = version + u16(1) + u16(1) + bytes([0xF1, 0, 0]) + bytes(range(12))  # global table, 4 colours
    return header + b"".join(blocks) + (b"\x3b" if trailer else b"")


def status_map(report):
    return {c["id"]: c["status"] for c in report.checks}


def check_of(report, check_id):
    return next(c for c in report.checks if c["id"] == check_id)


def cli(*args):
    proc = subprocess.run([sys.executable, "-I", "-B", GIF_SCRIPT] + list(args), capture_output=True)
    return proc.returncode, proc.stdout.decode("utf-8", "replace"), proc.stderr.decode("utf-8", "replace")


def setUpModule():
    if not FFMPEG or not FFPROBE:
        raise unittest.SkipTest("ffmpeg and ffprobe are required on PATH")
    os.makedirs(WORK, exist_ok=True)
    F["g24"] = ffmpeg_gif("g24.gif", fps=24, frames=24)             # 1 s at 24 fps
    F["f24"] = ffmpeg_gif("f24.gif", fps=24, frames=48)             # 2 s at 24, 25, 30 fps
    F["f25"] = ffmpeg_gif("f25.gif", fps=25, frames=50)
    F["f30"] = ffmpeg_gif("f30.gif", fps=30, frames=60)
    F["noloop"] = ffmpeg_gif("noloop.gif", fps=24, frames=24, extra=["-loop", "-1"])
    F["one"] = ffmpeg_gif("one.gif", fps=24, frames=1)
    F["perframe"] = ffmpeg_gif(
        "perframe.gif", fps=24, frames=24,
        graph="split[a][b];[a]palettegen=stats_mode=single[p];[b][p]paletteuse=new=1")


# ---------------------------------------------------------------------------
# Parser structure
# ---------------------------------------------------------------------------

class ParserStructure(unittest.TestCase):
    def test_ffmpeg_gif_basic_facts(self):
        gif = qa_gif.parse_gif(F["g24"])
        self.assertEqual(len(gif["frames"]), 24)
        self.assertEqual((gif["screen_width"], gif["screen_height"]), (64, 48))
        self.assertEqual(gif["version"], "GIF89a")
        self.assertEqual(gif["loop_count"], 0)
        self.assertEqual(gif["trailing_bytes"], 0)
        # negative control: another file must not give the same frame count
        self.assertNotEqual(len(qa_gif.parse_gif(F["f25"])["frames"]), 24)

    def test_delays_match_the_ffprobe_oracle(self):
        for name in ("g24", "f25", "f30", "perframe"):
            mine = [f["delay_cs"] for f in qa_gif.parse_gif(F[name])["frames"]]
            self.assertEqual(mine, oracle_delays(F[name]), name)
        # delays the parser must read back after a patch (all >= 1: ffprobe maps 0 to 10)
        wanted = [(k * 37) % 300 + 1 for k in range(24)]
        path = write("varied.gif", patch_delays(read(F["g24"]), wanted))
        self.assertEqual([f["delay_cs"] for f in qa_gif.parse_gif(path)["frames"]], wanted)
        self.assertEqual(oracle_delays(path), wanted)
        # negative control: the unpatched file does not carry those delays
        self.assertNotEqual(oracle_delays(F["g24"]), wanted)

    def test_largest_delay_value_is_read_unsigned(self):
        path = write("maxdelay.gif", build_gif([b_netscape(0), b_frame(65535), b_frame(1)]))
        info = qa_gif.build_report(path).info
        self.assertEqual(info["delays_cs"], [65535, 1])
        self.assertAlmostEqual(info["nominal_duration_s"], 655.36)

    def test_local_colour_tables_from_ffmpeg_per_frame_palettes(self):
        data = read(F["perframe"])
        expected = sum(1 for off in gce_offsets(data, 24) if data[off + 17] & 0x80)  # independent count
        self.assertGreater(expected, 0)
        info = qa_gif.build_report(F["perframe"]).info
        self.assertEqual(info["local_colour_table_frames"], expected)
        self.assertEqual(info["frame_count"], 24)
        # negative control: a plain ffmpeg GIF has a global table and no local tables
        plain = qa_gif.build_report(F["g24"]).info
        self.assertEqual(plain["local_colour_table_frames"], 0)
        self.assertEqual(plain["global_colour_table_entries"], 256)

    def test_local_and_global_tables_in_a_hand_built_gif(self):
        path = write("tables.gif", build_gif([b_frame(4, local=False), b_frame(4, local=True), b_frame(4)]))
        info = qa_gif.build_report(path).info
        self.assertEqual(info["global_colour_table_entries"], 4)
        self.assertEqual(info["local_colour_table_frames"], 1)
        # the fixture is a valid GIF according to ffmpeg, so the test is about real GIFs
        self.assertEqual(decoded_frame_count(path), 3)
        # negative control: without the local flag the count is zero
        none = write("tables_none.gif", build_gif([b_frame(4), b_frame(4)]))
        self.assertEqual(qa_gif.build_report(none).info["local_colour_table_frames"], 0)

    def test_interlaced_frames(self):
        patched = patch_interlace(read(F["g24"]))
        path = write("interlaced.gif", patched)
        self.assertEqual(qa_gif.build_report(path).info["interlaced_frames"], 24)
        self.assertEqual(qa_gif.build_report(path).info["frame_count"], 24)
        self.assertEqual(decoded_frame_count(path), 24)  # still a GIF ffmpeg can read
        # negative control: the unpatched file has none
        self.assertEqual(qa_gif.build_report(F["g24"]).info["interlaced_frames"], 0)
        # hand-built: only the flagged frame counts
        built = write("interlaced_built.gif", build_gif([b_frame(4, interlaced=True), b_frame(4)]))
        self.assertEqual(qa_gif.build_report(built).info["interlaced_frames"], 1)

    def test_extensions_are_skipped_and_never_counted_as_frames(self):
        blocks = [
            b_comment(b"first comment " + b"x" * 300),                  # spans two sub-blocks
            b_netscape(0),
            b_application(b"XMP DataXMP", b"<xmp/>" * 80),             # long non-loop application data
            b_gce(77), b_plain_text(b"plain text"),                    # a delay that belongs to the text, not a frame
            b_frame(5, local=True, interlaced=True),
            b_comment(b"between frames"),
            b"\x21\x99" + sub_blocks(b"unknown extension body"),      # unknown extension label
            b_frame(6),
        ]
        path = write("kitchen_sink.gif", build_gif(blocks))
        info = qa_gif.build_report(path).info
        self.assertEqual(info["frame_count"], 2)
        self.assertEqual(info["delays_cs"], [5, 6])          # 77 was not given to a frame
        self.assertEqual(info["comment_blocks"], 2)
        self.assertEqual(info["plain_text_extensions"], 1)
        self.assertEqual(info["unknown_extensions"], ["0x99"])
        self.assertEqual(info["loop"]["loop_count"], 0)
        self.assertIn("XMP DataXMP", info["application_extensions"])
        self.assertEqual(info["local_colour_table_frames"], 1)
        self.assertEqual(info["interlaced_frames"], 1)
        # negative control: the same two frames without any extension report none of them
        bare = qa_gif.build_report(write("bare.gif", build_gif([b_frame(5), b_frame(6)]))).info
        self.assertEqual((bare["comment_blocks"], bare["plain_text_extensions"], bare["unknown_extensions"]),
                         (0, 0, []))
        self.assertEqual(bare["delays_cs"], [5, 6])

    def test_comment_text_is_reported_as_ascii(self):
        path = write("comment_bytes.gif", build_gif([b_comment(bytes([0x63, 0x61, 0x66, 0xC3, 0xA9])), b_frame(), b_frame()]))
        text = qa_gif.build_report(path).info["comments"][0]
        self.assertTrue(all(ord(c) < 128 for c in text))
        self.assertTrue(text.startswith("caf"))

    def test_gif87a_without_graphic_control_extensions(self):
        path = write("g87.gif", build_gif([b_frame(with_gce=False), b_frame(with_gce=False)], version=b"GIF87a"))
        report = qa_gif.build_report(path)
        self.assertEqual(report.info["format"], "GIF87a")
        self.assertEqual(report.info["frames_without_graphic_control"], 2)
        self.assertEqual(report.info["delays_cs"], [0, 0])
        # such frames play at the browser default, so the effective duration check must warn
        self.assertEqual(status_map(report)["effective_duration"], common.WARN)
        self.assertAlmostEqual(report.info["effective_duration_s"], 0.2)

    def test_single_frame_animated_gif(self):
        # ffmpeg's own one-frame GIF carries a loop extension: an "animated" GIF with one frame
        info = qa_gif.build_report(F["one"]).info
        self.assertEqual(info["frame_count"], 1)
        self.assertTrue(info["loop"]["extension_present"])
        built = write("one_built.gif", build_gif([b_netscape(0), b_frame(10)]))
        report = qa_gif.build_report(built, fps=24)
        self.assertEqual(report.info["frame_count"], 1)
        states = status_map(report)
        self.assertEqual(states["frame_count"], common.WARN)   # a still image, said plainly
        self.assertEqual(states["loop"], common.SKIP)
        # negative control: --expect-frames 1 makes the single frame the expected outcome
        self.assertEqual(status_map(qa_gif.build_report(built, expect_frames=1))["frame_count"], common.PASS)

    def test_padding_and_trailing_bytes_are_tolerated_and_counted(self):
        padded = build_gif([b_frame(), b"\x00\x00\x00", b_frame()]) + b"junk"
        info = qa_gif.build_report(write("padded.gif", padded)).info
        self.assertEqual(info["frame_count"], 2)
        self.assertEqual(info["stray_zero_bytes"], 3)
        self.assertEqual(info["trailing_bytes_after_trailer"], 4)
        clean = qa_gif.build_report(write("unpadded.gif", build_gif([b_frame(), b_frame()]))).info
        self.assertEqual((clean["stray_zero_bytes"], clean["trailing_bytes_after_trailer"]), (0, 0))


# ---------------------------------------------------------------------------
# Malformed and truncated files
# ---------------------------------------------------------------------------

class MalformedFiles(unittest.TestCase):
    def test_every_truncation_of_a_valid_gif_is_a_clear_error(self):
        samples = {
            "ffmpeg": read(F["g24"]),
            "per-frame palettes": read(F["perframe"]),
            "extensions": build_gif([b_comment(b"c" * 300), b_netscape(0), b_gce(9), b_plain_text(b"t"),
                                     b_frame(5, local=True), b"\x21\x99" + sub_blocks(b"u"), b_frame(6)]),
        }
        started = time.time()
        for label, data in samples.items():
            qa_gif._parse_stream(io.BytesIO(data))  # the complete file parses (positive control)
            for length in range(len(data)):
                with self.assertRaises(qa_gif.GifFormatError, msg="%s cut at %d" % (label, length)) as ctx:
                    qa_gif._parse_stream(io.BytesIO(data[:length]))
                self.assertIn("truncated GIF", str(ctx.exception))
        self.assertLess(time.time() - started, 60, "truncation scan took too long (possible hang)")

    def test_single_byte_corruption_never_crashes_or_hangs(self):
        data = build_gif([b_comment(b"hello"), b_netscape(0), b_gce(9), b_plain_text(b"t"),
                          b_frame(5, local=True), b_frame(6, interlaced=True)])
        outcomes = {"parsed": 0, "rejected": 0}
        started = time.time()
        for pos in range(len(data)):
            for value in (0x00, 0x21, 0x2C, 0x3B, 0xFF):
                mutated = data[:pos] + bytes([value]) + data[pos + 1:]
                try:
                    qa_gif._parse_stream(io.BytesIO(mutated))
                    outcomes["parsed"] += 1
                except qa_gif.GifFormatError:
                    outcomes["rejected"] += 1  # any other exception type propagates and fails the test
        self.assertLess(time.time() - started, 60)
        # the scan is not vacuous: some mutations are survivable, some are rejected
        self.assertGreater(outcomes["parsed"], 0)
        self.assertGreater(outcomes["rejected"], 0)

    def test_not_a_gif_is_rejected_with_a_clear_message(self):
        samples = {
            "empty": b"",
            "png": b"\x89PNG\r\n\x1a\n" + b"\x00" * 40,
            "text": b"this is not a gif at all",
            "short": b"GIF89",
        }
        for label, data in samples.items():
            with self.assertRaises(qa_gif.GifFormatError, msg=label):
                qa_gif._parse_stream(io.BytesIO(data))
        with self.assertRaises(qa_gif.GifFormatError) as ctx:
            qa_gif._parse_stream(io.BytesIO(samples["png"]))
        self.assertIn("not a GIF", str(ctx.exception))

    def test_corrupt_block_bytes_are_rejected(self):
        bad_block = build_gif([b_frame(), b"\x55", b_frame()])
        with self.assertRaises(qa_gif.GifFormatError) as ctx:
            qa_gif._parse_stream(io.BytesIO(bad_block))
        self.assertIn("0x55", str(ctx.exception))
        bad_gce = build_gif([b"\x21\xf9\x02\x00\x04\x00\x00", b_frame()])  # block size 2 instead of 4
        with self.assertRaises(qa_gif.GifFormatError) as ctx:
            qa_gif._parse_stream(io.BytesIO(bad_gce))
        self.assertIn("block size", str(ctx.exception))

    def test_missing_trailer_is_an_error_not_a_pass(self):
        data = build_gif([b_frame(), b_frame()], trailer=False)
        with self.assertRaises(qa_gif.GifFormatError) as ctx:
            qa_gif._parse_stream(io.BytesIO(data))
        self.assertIn("trailer", str(ctx.exception))
        qa_gif._parse_stream(io.BytesIO(build_gif([b_frame(), b_frame()])))  # with the trailer it parses

    def test_a_flood_of_padding_bytes_ends_quickly(self):
        data = build_gif([]) [:-1] + b"\x00" * 1000000  # no trailer, a million zero bytes
        started = time.time()
        with self.assertRaises(qa_gif.GifFormatError):
            qa_gif._parse_stream(io.BytesIO(data))
        self.assertLess(time.time() - started, 30)

    def test_unreadable_paths_are_usage_errors(self):
        with self.assertRaises(common.UsageError):
            qa_gif.build_report(os.path.join(WORK, "does_not_exist.gif"))
        with self.assertRaises(common.UsageError):
            qa_gif.build_report(WORK)  # a directory
        # negative control: an existing GIF does not raise
        qa_gif.build_report(F["g24"])


# ---------------------------------------------------------------------------
# The checks
# ---------------------------------------------------------------------------

class FrameCountAndDuration(unittest.TestCase):
    def test_frame_count(self):
        self.assertEqual(status_map(qa_gif.build_report(F["g24"], expect_frames=24))["frame_count"], common.PASS)
        wrong = qa_gif.build_report(F["g24"], expect_frames=25)
        self.assertEqual(status_map(wrong)["frame_count"], common.FAIL)
        self.assertEqual(check_of(wrong, "frame_count")["actual"], 24)
        # no expectation: an animated GIF is measured and passes the ">= 2" rule
        self.assertEqual(status_map(qa_gif.build_report(F["g24"]))["frame_count"], common.PASS)

    def test_a_gif_with_no_image_frames_fails_and_never_passes_on_empty_data(self):
        path = write("zero_frames.gif", build_gif([b_netscape(0)]))
        report = qa_gif.build_report(path, fps=24, expect_duration=1.0)
        states = status_map(report)
        self.assertEqual(states["frame_count"], common.FAIL)
        for check_id in ("duration", "effective_duration", "rounding_drift", "loop"):
            self.assertEqual(states[check_id], common.SKIP, check_id)
        self.assertEqual(report.overall(), common.FAIL)

    def test_duration(self):
        ok = qa_gif.build_report(F["f24"], expect_duration=2.0)
        self.assertEqual(status_map(ok)["duration"], common.PASS)
        bad = qa_gif.build_report(F["f24"], expect_duration=2.5)
        self.assertEqual(status_map(bad)["duration"], common.FAIL)
        self.assertAlmostEqual(check_of(bad, "duration")["actual"], 2.0)
        # tolerance is honoured in both directions
        self.assertEqual(status_map(qa_gif.build_report(F["f24"], expect_duration=2.01))["duration"], common.PASS)
        self.assertEqual(status_map(qa_gif.build_report(F["f24"], expect_duration=2.05))["duration"], common.FAIL)
        self.assertEqual(status_map(qa_gif.build_report(F["f24"], expect_duration=2.05, tol=0.1))["duration"],
                         common.PASS)
        # without an expectation nothing was compared, so it is SKIP, never PASS
        self.assertEqual(status_map(qa_gif.build_report(F["f24"]))["duration"], common.SKIP)

    def test_effective_duration_flags_delays_of_zero_and_one(self):
        base = read(F["g24"])
        for delay, expected in ((0, common.WARN), (1, common.WARN), (2, common.PASS), (4, common.PASS)):
            path = write("delay_%d.gif" % delay, patch_delays(base, delay))
            report = qa_gif.build_report(path)
            self.assertEqual(status_map(report)["effective_duration"], expected, "delay %d" % delay)
        zero = qa_gif.build_report(write("delay_0.gif", patch_delays(base, 0)))
        self.assertAlmostEqual(zero.info["nominal_duration_s"], 0.0)
        self.assertAlmostEqual(zero.info["effective_duration_s"], 2.4)    # 24 frames x 10 cs
        self.assertEqual(zero.info["frames_with_delay_0_or_1"], 24)
        self.assertIn("0 or 1 cs", check_of(zero, "effective_duration")["detail"])
        # one slow frame among good ones is still reported, with its count
        mixed = [0] + [4] * 23
        report = qa_gif.build_report(write("mixed_zero.gif", patch_delays(base, mixed)))
        self.assertEqual(report.info["frames_with_delay_0_or_1"], 1)
        self.assertEqual(status_map(report)["effective_duration"], common.WARN)
        # it can only warn: the file itself is a legal GIF and the rule is a browser convention
        self.assertNotEqual(status_map(qa_gif.build_report(write("delay_0.gif", patch_delays(base, 0))))
                            ["effective_duration"], common.FAIL)

    def test_effective_duration_compares_with_the_expected_duration_when_it_matters(self):
        path = write("delay_1.gif", patch_delays(read(F["g24"]), 1))   # written 0.24 s, played 2.40 s
        report = qa_gif.build_report(path, expect_duration=0.24)
        self.assertEqual(status_map(report)["duration"], common.PASS)            # the file says 0.24 s
        self.assertEqual(status_map(report)["effective_duration"], common.WARN)  # a browser plays 2.40 s
        self.assertIn("2.40", check_of(report, "effective_duration")["detail"])


class RoundingDrift(unittest.TestCase):
    def test_uniform_four_centisecond_delays_at_24_fps_fail(self):
        # the contract example: 24 frames, every delay 4 cs, intended 24 fps
        path = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        report = qa_gif.build_report(path, fps=24)
        check = check_of(report, "rounding_drift")
        self.assertEqual(check["status"], common.FAIL)
        self.assertAlmostEqual(check["actual"], 0.96)
        self.assertAlmostEqual(check["expected"], 1.0)
        self.assertIn("fast", check["detail"])
        self.assertIn("4.2%", check["detail"])               # 1.00 / 0.96 = 4.2 percent fast
        self.assertEqual(report.overall(), common.FAIL)

    def test_negative_controls_for_the_drift_check(self):
        uniform = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        # the same file is exactly right for 25 fps (24 frames x 4 cs = 0.96 s)
        self.assertEqual(status_map(qa_gif.build_report(uniform, fps=25))["rounding_drift"], common.PASS)
        # a wider tolerance accepts the 0.04 s drift
        self.assertEqual(status_map(qa_gif.build_report(uniform, fps=24, tol=0.05))["rounding_drift"], common.PASS)
        # ffmpeg's own 24 fps GIF distributes the rounding (4 and 5 cs) and passes
        own = qa_gif.build_report(F["g24"], fps=24)
        self.assertEqual(status_map(own)["rounding_drift"], common.PASS)
        self.assertEqual(sorted(own.info["delay_histogram"]), [4, 5])
        # without --fps the check cannot run and says so
        skipped = qa_gif.build_report(uniform)
        self.assertEqual(status_map(skipped)["rounding_drift"], common.SKIP)
        self.assertIn("--fps", check_of(skipped, "rounding_drift")["detail"])

    def test_ffmpeg_made_gifs_pass_at_24_25_and_30_fps_and_fail_at_the_wrong_rate(self):
        for name, fps in (("f24", 24), ("f25", 25), ("f30", 30)):
            self.assertEqual(status_map(qa_gif.build_report(F[name], fps=fps, expect_duration=2.0))
                             ["rounding_drift"], common.PASS, name)
        # a deliberately wrong intended rate must not pass. ffmpeg's 30 fps GIF has mixed delays (3 and 4 cs),
        # so it is not the uniform-rounding signature: the check warns and reports the drift instead of failing
        wrong = qa_gif.build_report(F["f30"], fps=24)
        self.assertEqual(status_map(wrong)["rounding_drift"], common.WARN)
        self.assertIn("not the uniform-rounding signature", check_of(wrong, "rounding_drift")["detail"])
        self.assertAlmostEqual(check_of(wrong, "rounding_drift")["actual"], 2.0)
        self.assertAlmostEqual(check_of(wrong, "rounding_drift")["expected"], 2.5)
        # the 25 fps GIF (uniform 4 cs) is the uniform signature at 24 fps and fails
        self.assertEqual(status_map(qa_gif.build_report(F["f25"], fps=24))["rounding_drift"], common.FAIL)

    def test_fractional_and_decimal_rates_are_accepted(self):
        path = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        for rate in ("24000/1001", "23.976", 24, "24"):
            self.assertEqual(status_map(qa_gif.build_report(path, fps=rate))["rounding_drift"], common.FAIL, rate)
        with self.assertRaises(common.UsageError):
            qa_gif.build_report(path, fps="not-a-number")
        with self.assertRaises(common.UsageError):
            qa_gif.build_report(path, fps=0)

    def test_uniform_three_centiseconds_at_30_fps_fails_and_names_the_fix(self):
        path = write("uniform3_30.gif", patch_delays(read(F["f30"]), 3))
        check = check_of(qa_gif.build_report(path, fps=30), "rounding_drift")
        self.assertEqual(check["status"], common.FAIL)
        self.assertIn("3 and 4", check["detail"])             # mix 3 and 4 cs

    def test_a_gif_exported_at_the_wrong_frame_rate_is_described_as_a_factor_with_the_right_cause(self):
        # 2 cs delays are 50 fps: 2.08 times too fast for an intended 24 fps. The old text said "108.3% fast"
        # and blamed delay rounding, which cannot explain an error of more than a factor of two.
        path = write("uniform2_24.gif", patch_delays(read(F["g24"]), 2))
        check = check_of(qa_gif.build_report(path, fps=24), "rounding_drift")
        self.assertEqual(check["status"], common.FAIL)
        self.assertIn("plays about 2.08 times as fast as 24 fps", check["detail"])
        self.assertIn("a delay of 2 cs is 50 fps", check["detail"])
        self.assertIn("different frame rate", check["detail"])
        self.assertNotIn("108", check["detail"])
        self.assertNotIn("mix", check["detail"])

    def test_a_gif_that_is_too_slow_by_a_factor_says_so(self):
        path = write("uniform10_24.gif", patch_delays(read(F["g24"]), 10))   # 10 cs = 10 fps
        detail = check_of(qa_gif.build_report(path, fps=24), "rounding_drift")["detail"]
        self.assertIn("plays about 2.40 times as slow as 24 fps", detail)
        self.assertIn("a delay of 10 cs is 10 fps", detail)

    def test_small_errors_stay_a_percentage_with_the_rounding_advice(self):
        # Negative control for the wording above: 4 cs at 24 fps is rounding, so percent and "mix" remain.
        path = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        detail = check_of(qa_gif.build_report(path, fps=24), "rounding_drift")["detail"]
        self.assertIn("plays about 4.2% fast", detail)
        self.assertIn("mix 4 and 5 cs", detail)
        self.assertNotIn("times as", detail)
        self.assertNotIn("different frame rate", detail)

    def test_the_implied_frame_rate_is_reported_without_any_intended_speed(self):
        # "This GIF looks too fast" with no numbers given: the tool must still say what speed the file asks for.
        uniform = qa_gif.build_report(write("uniform4_24.gif", patch_delays(read(F["g24"]), 4)))
        self.assertEqual(uniform.info["implied_fps"], 25.0)
        self.assertIn("= 25 fps", check_of(uniform, "duration")["detail"])
        self.assertIn("plays at 25 fps", check_of(uniform, "rounding_drift")["detail"])
        self.assertEqual(status_map(uniform)["duration"], common.SKIP)
        # Negative control: ffmpeg's own 24 fps GIF reads 24, so the number is measured, not a constant.
        own = qa_gif.build_report(F["g24"])
        self.assertEqual(own.info["implied_fps"], 24.0)
        self.assertIn("= 24 fps", check_of(own, "duration")["detail"])
        fast = qa_gif.build_report(write("uniform2_24.gif", patch_delays(read(F["g24"]), 2)))
        self.assertEqual(fast.info["implied_fps"], 50.0)

    def test_implied_frame_rates_when_the_delays_are_zero(self):
        report = qa_gif.build_report(write("zero_delays.gif", patch_delays(read(F["g24"]), 0)))
        self.assertIsNone(report.info["implied_fps"])
        self.assertEqual(report.info["implied_fps_in_browsers"], 10.0)   # browsers play 0 as 10 cs
        self.assertIn("all delays are 0", check_of(report, "duration")["detail"])

    def test_the_table_lists_what_was_not_measured(self):
        text = qa_gif.build_report(F["g24"]).table()
        self.assertIn("Not measured (SKIP, proves nothing): duration, rounding_drift", text)
        self.assertNotIn("Not measured", qa_gif.build_report(F["g24"], fps=24, expect_duration=1.0).table())

    def test_a_held_last_frame_is_a_warning_not_the_rounding_signature(self):
        delays = [4] * 23 + [200]                              # intentional two-second hold at the end
        path = write("held.gif", patch_delays(read(F["g24"]), delays))
        report = qa_gif.build_report(path, fps=24)
        self.assertEqual(status_map(report)["rounding_drift"], common.WARN)
        self.assertNotEqual(report.overall(), common.FAIL)

    def test_exactly_matching_uniform_delays_pass(self):
        path = write("uniform5_20.gif", patch_delays(read(F["g24"]), 5))   # 24 x 5 cs = 1.20 s = 24 / 20 fps
        report = qa_gif.build_report(path, fps=20)
        self.assertEqual(status_map(report)["rounding_drift"], common.PASS)
        self.assertEqual(status_map(qa_gif.build_report(path, fps=24))["rounding_drift"], common.FAIL)


class LoopCheck(unittest.TestCase):
    def test_loop_forever_passes_and_other_cases_are_reported(self):
        self.assertEqual(status_map(qa_gif.build_report(F["g24"]))["loop"], common.PASS)
        none = qa_gif.build_report(F["noloop"])
        self.assertEqual(status_map(none)["loop"], common.WARN)
        self.assertIn("once", check_of(none, "loop")["detail"])
        three = qa_gif.build_report(write("loop3.gif", patch_loop(read(F["g24"]), 3)))
        self.assertEqual(status_map(three)["loop"], common.WARN)
        self.assertEqual(check_of(three, "loop")["actual"], 3)
        # the patch really changed the file (negative control for the patch helper)
        self.assertNotEqual(read(F["g24"]), patch_loop(read(F["g24"]), 3))

    def test_single_frame_loop_is_skipped(self):
        self.assertEqual(status_map(qa_gif.build_report(F["one"]))["loop"], common.SKIP)

    def test_animexts_loop_extension_is_recognised(self):
        data = build_gif([b_application(b"ANIMEXTS1.0", b"\x01" + u16(0)), b_frame(), b_frame()])
        self.assertEqual(status_map(qa_gif.build_report(write("animexts.gif", data)))["loop"], common.PASS)
        other = build_gif([b_application(b"SOMEOTHER01", b"\x01" + u16(0)), b_frame(), b_frame()])
        self.assertEqual(status_map(qa_gif.build_report(write("other_app.gif", other)))["loop"], common.WARN)


class MeasuredFfmpegDelays(unittest.TestCase):
    def test_record_what_ffmpeg_writes_at_24_25_and_30_fps(self):
        facts = {}
        for name, fps in (("f24", 24), ("f25", 25), ("f30", 30)):
            info = qa_gif.build_report(F[name]).info
            frames = info["frame_count"]
            facts[str(fps)] = {
                "frames": frames,
                "first_delays_cs": info["delays_cs"][:12],
                "delay_histogram_cs": info["delay_histogram"],
                "nominal_duration_s": info["nominal_duration_s"],
                "effective_duration_s": info["effective_duration_s"],
                "ideal_duration_s": frames / float(fps),
            }
            # ffmpeg does not suffer from uniform rounding: nominal matches frames / fps
            self.assertAlmostEqual(info["nominal_duration_s"], frames / float(fps), delta=0.02, msg=name)
            # and no frame is slow enough for browsers to override
            self.assertEqual(info["effective_duration_s"], info["nominal_duration_s"], name)
        # a uniform-delay GIF would be wrong at 24 fps: its nominal length is 4 percent short
        uniform = qa_gif.build_report(write("uniform4_f24.gif", patch_delays(read(F["f24"]), 4))).info
        self.assertGreater(abs(uniform["nominal_duration_s"] - 2.0), 0.02)
        with open(os.path.join(os.path.dirname(WORK), "measured_gif_delays.json"), "w") as fh:
            json.dump(facts, fh, indent=2)


