class CommandLine(unittest.TestCase):
    def test_exit_codes_0_1_2(self):
        uniform = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        code, out, err = cli(F["g24"], "--fps", "24")
        self.assertEqual(code, 0, out + err)
        self.assertIn("qa_gif.py: PASS", out)
        code, out, err = cli(uniform, "--fps", "24")
        self.assertEqual(code, 1, out + err)
        self.assertIn("[FAIL] rounding_drift", out)
        code, out, err = cli(os.path.join(WORK, "missing.gif"))
        self.assertEqual(code, 2)
        self.assertIn("error:", err)
        self.assertEqual(out.strip(), "")

    def test_warn_only_exits_zero(self):
        code, out, err = cli(F["noloop"])
        self.assertEqual(code, 0, out + err)
        self.assertIn("[WARN] loop", out)

    def test_skip_is_listed_and_not_a_pass(self):
        code, out, err = cli(F["g24"])
        self.assertEqual(code, 0)
        self.assertRegex(out, r"\[SKIP\] duration")
        self.assertRegex(out, r"\[SKIP\] rounding_drift")
        self.assertNotRegex(out, r"\[PASS\] (duration|rounding_drift)")

    def test_truncated_and_corrupt_files_exit_2_with_a_message(self):
        data = read(F["g24"])
        cut = write("cut.gif", data[:len(data) // 2])
        code, out, err = cli(cut)
        self.assertEqual(code, 2)
        self.assertIn("truncated GIF", err)
        self.assertNotIn("PASS", out)
        not_gif = write("not_a_gif.gif", b"\x89PNG\r\n\x1a\n" + b"\x00" * 64)
        code, out, err = cli(not_gif)
        self.assertEqual(code, 2)
        self.assertIn("not a GIF", err)
        # negative control: the uncut file still exits 0
        self.assertEqual(cli(F["g24"])[0], 0)

    def test_bad_arguments_exit_2(self):
        for args in (["--fps", "0"], ["--fps", "abc"], ["--tol", "-1"], ["--expect-frames", "-3"],
                     ["--expect-duration", "nan"], ["--expect-frames", "x"]):
            code, out, err = cli(F["g24"], *args)
            self.assertEqual(code, 2, args)
        self.assertEqual(subprocess.run([sys.executable, "-I", "-B", GIF_SCRIPT], capture_output=True).returncode, 2)

    def test_json_output_schema_and_provenance(self):
        code, out, err = cli(F["g24"], "--fps", "24", "--expect-frames", "24", "--expect-duration", "1.0", "--json")
        self.assertEqual(code, 0, err)
        doc = json.loads(out)
        self.assertEqual(set(doc), {"tool", "file", "overall", "checks", "info", "provenance"})
        self.assertEqual(doc["tool"], "qa_gif.py")
        self.assertEqual(doc["overall"], "PASS")
        self.assertEqual([c["id"] for c in doc["checks"]],
                         ["frame_count", "duration", "effective_duration", "rounding_drift", "loop"])
        for c in doc["checks"]:
            self.assertEqual(set(c), {"id", "status", "expected", "actual", "detail"})
            self.assertIn(c["status"], ("PASS", "WARN", "FAIL", "SKIP"))
        prov = doc["provenance"]
        self.assertEqual(prov["script"], "qa_gif.py")
        self.assertEqual(prov["version"], common.VERSION)
        self.assertEqual(prov["input"]["sha256"], hashlib.sha256(read(F["g24"])).hexdigest())
        self.assertEqual(prov["input"]["size_bytes"], os.path.getsize(F["g24"]))
        self.assertEqual(prov["commands"], [])               # this script runs no external command
        self.assertIsNone(prov["ffmpeg_version"])
        self.assertIsNone(prov["spec_sha256"])
        # negative control: a different file has a different recorded hash
        other = json.loads(cli(F["f25"], "--json")[1])
        self.assertNotEqual(other["provenance"]["input"]["sha256"], prov["input"]["sha256"])

    def test_json_overall_matches_the_worst_check(self):
        uniform = write("uniform4_24.gif", patch_delays(read(F["g24"]), 4))
        doc = json.loads(cli(uniform, "--fps", "24", "--json")[1])
        self.assertEqual(doc["overall"], "FAIL")
        self.assertIn("FAIL", [c["status"] for c in doc["checks"]])
        doc = json.loads(cli(F["noloop"], "--json")[1])
        self.assertEqual(doc["overall"], "WARN")
        self.assertNotIn("FAIL", [c["status"] for c in doc["checks"]])

    def test_json_is_ascii_even_for_odd_comment_bytes(self):
        data = build_gif([b_comment(b"\xff\xfe\x80 odd bytes"), b_frame(), b_frame()])
        out = cli(write("odd_comment.gif", data), "--json")[1]
        out.encode("ascii")  # raises if any non-ASCII character was printed

    def test_ffmpeg_arguments_are_accepted_and_ignored(self):
        code, out, err = cli(F["g24"], "--ffmpeg", "no-such-ffmpeg", "--ffprobe", "no-such-ffprobe")
        self.assertEqual(code, 0, err)


# ---------------------------------------------------------------------------
# Hard rules for the two files this builder owns
# ---------------------------------------------------------------------------

FORBIDDEN_IMPORTS = {"socket", "urllib", "http", "requests", "ftplib", "smtplib", "pickle", "marshal", "ctypes",
                     "base64", "subprocess"}
FORBIDDEN_NAMES = {"eval", "exec", "compile", "__import__", "getenv", "environ", "system", "popen"}


def rule_violations(source):
    """Names from the contract's hard rule 2 that a source text uses."""
    found = []
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, ast.Import):
            found += [a.name.split(".")[0] for a in node.names if a.name.split(".")[0] in FORBIDDEN_IMPORTS]
        elif isinstance(node, ast.ImportFrom) and node.module and node.module.split(".")[0] in FORBIDDEN_IMPORTS:
            found.append(node.module)
        elif isinstance(node, ast.Name) and node.id in FORBIDDEN_NAMES:
            found.append(node.id)
        elif isinstance(node, ast.Attribute) and node.attr in FORBIDDEN_NAMES:
            found.append(node.attr)
        elif isinstance(node, ast.keyword) and node.arg == "shell":
            found.append("shell=")
    return found


class HardRules(unittest.TestCase):
    def test_scanner_catches_violations_and_passes_clean_code(self):
        bad = "import socket\nimport os\nx = eval('1')\nos.system('x')\nos.environ\nimport subprocess\nf(shell=True)\n"
        self.assertEqual(sorted(set(rule_violations(bad))),
                         sorted(["socket", "eval", "system", "environ", "subprocess", "shell="]))
        self.assertEqual(rule_violations("import os\nprint(os.path.join('a', 'b'))\n"), [])

    def test_qa_gif_obeys_the_hard_rules(self):
        raw = read(GIF_SCRIPT)
        self.assertEqual(rule_violations(raw.decode("utf-8")), [])
        self.assertNotIn(b"\r", raw, "LF line endings only")
        raw.decode("ascii")  # ASCII-only source
        lines = raw.decode("ascii").split("\n")
        self.assertEqual(lines[0], "#!/usr/bin/env python3")
        header = "\n".join(line for line in lines[1:25] if line.startswith("#"))
        for word in ("Purpose", "Inputs", "Outputs", "Exit codes"):
            self.assertIn(word, header)
        self.assertNotIn("\x00", raw.decode("ascii"))

    def test_qa_gif_never_writes_to_disk(self):
        # rule 3 is satisfied by construction: the script opens files only for reading
        tree = ast.parse(read(GIF_SCRIPT).decode("utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and getattr(node.func, "id", "") == "open":
                modes = [a.value for a in node.args[1:2] if isinstance(a, ast.Constant)]
                self.assertEqual(modes, ["rb"])

    def test_no_bytecode_left_in_the_package(self):
        self.assertFalse(os.path.isdir(os.path.join(SCRIPTS, "__pycache__")))


if __name__ == "__main__":
    unittest.main()
